/** Hình que tính ghép từ các đa giác (cạnh chung chỉ tính một que). */
const sticks = (...polys) => {
  const pts = {}, segs = [], seen = new Set();
  for (const p of polys) p.forEach((a, i) => {
    const b = p[(i + 1) % p.length], ka = a.join(','), kb = b.join(',');
    pts[ka] = a; pts[kb] = b;
    const key = [ka, kb].sort().join('|');
    if (!seen.has(key)) { seen.add(key); segs.push([ka, kb]); }
  });
  return { type: 'lines', match: true, pts, segs };
};
const SQ = (x, y) => [[x, y], [x + 2, y], [x + 2, y + 2], [x, y + 2]];
/** n tam giác que xếp một hàng (úp, ngửa xen kẽ). */
const triRow = (n) => sticks(...Array.from({ length: n }, (_, k) => {
  const j = k >> 1;
  return k % 2 ? [[2 * j + 1, 0], [2 * j + 3, 0], [2 * j + 2, 2]] : [[2 * j, 2], [2 * j + 2, 2], [2 * j + 1, 0]];
}));
const sqRow = (n) => sticks(...Array.from({ length: n }, (_, k) => SQ(2 * k, 0)));
const sqGrid = (n) => sticks(...Array.from({ length: n * n }, (_, k) => SQ(2 * (k % n), 2 * Math.floor(k / n))));
const houses = (n) => sticks(...Array.from({ length: n }, (_, k) => [[2 * k, 0], [2 * k + 1, -2], [2 * k + 2, 0], [2 * k + 2, 2], [2 * k, 2]]));
const row = (...r) => ({ type: 'tokens', row: r.map(String) });
const rows = (...r) => ({ type: 'tokens', rows: r.map(x => x.map(String)) });
const clock = (h, m = 0) => ({ type: 'clock', h, m });
const ASK = { type: 'tokens', row: ['?'] };

